// Find the best path from src to dst in a directed weighted graph.
// The graph has vertices 0 .. n-1. Each edge (u, v, w) goes from u to v and
// costs w. Parallel edges and self-loops are allowed.
//
// The best path is the one with the smallest total weight; among those, the
// one with the fewest edges; among those, the lexicographically smallest list
// of vertices. Return the path as the list of its vertices, from src to dst
// inclusive. If src == dst the path is [src].
//
// Return [] when dst cannot be reached from src, and also when the input is
// invalid: n <= 0, src or dst outside 0 .. n-1, any edge endpoint outside
// 0 .. n-1, or any negative weight (anywhere in the list, even on an edge no
// path uses).
//
// Examples:
//   shortest_path(4, [(0, 1, 1), (1, 3, 1), (0, 2, 1), (2, 3, 1)], 0, 3) == [0, 1, 3]
//   shortest_path(3, [(0, 1, 5)], 0, 2) == []
fn shortest_path(n: Int, edges: List[(Int, Int, Int)], src: Int, dst: Int) -> List[Int] {
  let inside = |x: Int| x >= 0 && x < n;
  if n <= 0 || !inside(src) || !inside(dst) {
    return [];
  }
  if any(edges, |e| !inside(e.0) || !inside(e.1) || e.2 < 0) {
    return [];
  }
  // Dijkstra over (weight, path): the key only grows along an edge, so the
  // first time a vertex is picked its path is best under the full tie-break.
  let mut best: Map[Int, (Int, List[Int])] = map_from_list([(src, (0, [src]))]);
  let mut done: Set[Int] = set_new();
  while true {
    let mut pick: Option[Int] = None;
    for v in map_keys(best) {
      if !set_contains(done, v) {
        pick = match pick {
          None => Some(v),
          Some(p) => if key_less(best[v], best[p]) { Some(v) } else { Some(p) },
        };
      }
    }
    let u = match pick {
      None => { return []; },
      Some(u) => u,
    };
    if u == dst {
      return best[u].1;
    }
    done = set_add(done, u);
    let (d, path) = best[u];
    for (a, b, w) in edges {
      if a == u && !set_contains(done, b) {
        let cand = (d + w, push(path, b));
        let better = match map_get(best, b) {
          None => true,
          Some(old) => key_less(cand, old),
        };
        if better {
          best = map_set(best, b, cand);
        }
      }
    }
  }
  []
}

// Smaller weight, then fewer vertices, then lexicographically smaller path.
fn key_less(a: (Int, List[Int]), b: (Int, List[Int])) -> Bool {
  if a.0 != b.0 {
    a.0 < b.0
  } else if len(a.1) != len(b.1) {
    len(a.1) < len(b.1)
  } else {
    let mut i = 0;
    while i < len(a.1) {
      if a.1[i] != b.1[i] {
        return a.1[i] < b.1[i];
      }
      i = i + 1;
    }
    false
  }
}
